// Golden parity for frame() (delivery-policy spec DP2, DP10). The goldens are the exact
// output of this module's frame(), generated by scripts/gen-frame-goldens.mjs. The same
// cases live as tests/fixtures/delivery/frame-*.{json,txt}, which the Rust port
// (src/delivery/frame.rs) asserts byte for byte; a Rust test keeps this file's copy equal
// to them, because the plugin sandbox imports only files inside the mod's folder.
import { test, expect } from 'claude-code/testing'
import { frame } from '../hooks/register.js'
import goldens from './fixtures/frame-goldens.js'

const { header, ...cases } = goldens as Record<string, any>

for (const [name, golden] of Object.entries(cases)) {
  test(`frame() output equals the golden for ${name}`, () => {
    const got = frame(golden.items)
    expect(got).toBe(golden.text)
    expect(got.startsWith('/')).toBe(false)
  })
}

test('the golden cases cover every DP2 case', () => {
  expect(Object.keys(cases).sort()).toEqual(
    ['attention', 'controls', 'empty', 'markers', 'multiline', 'name-equals-id', 'tagged-ids'],
  )
})

test('frame() starts with the HEADER golden', () => {
  expect(frame([])).toBe(`${header}\n\n`)
  expect(frame([]).startsWith(header)).toBe(true)
})
